window.__votdWeek && window.__votdWeek({"week":"2027-12-27","reading":"","days":[{"d":"2027-12-27","ref":"2 Nephi 25:26","b":"2 Nephi","c":25,"v":26,"he":"וּמְדַבְּרִים עַל־הַמָּשִׁיחַ שְׂמֵחִים בַּמָּשִׁיחַ מַטִּיפִים עַל־הַמָּשִׁיחַ נִבָּאִים עַל־הַמָּשִׁיחַ וְכוֹתְבִים כִּנְבוּאוֹתֵינוּ לְמַעַן יֵדְעוּ בָנֵינוּ אֶל־מִי יִפְנוּ לִסְלִיחַת חַטֹּאתֵיהֶם׃","en":"And we talk of Christ, we rejoice in Christ, we preach of Christ, we prophesy of Christ, and we write according to our prophecies, that our children may know to what source they may look for a remission of their sins."},{"d":"2027-12-28","ref":"1 Nephi 6:4","b":"1 Nephi","c":6,"v":4,"he":"כִּי כׇל־חֶפְצִי לְהָשִׁיב אֶת־בְּנֵי הָאָדָם לָבוֹא אֶל־אֱלֹהֵי אַבְרָהָם וֵאלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב וּלְהִוָּשַׁע׃","en":"For the fulness of mine intent is that I may persuade men to come unto the God of Abraham, and the God of Isaac, and the God of Jacob, and be saved."},{"d":"2027-12-29","ref":"2 Nephi 29:7","b":"2 Nephi","c":29,"v":7,"he":"הֲלֹא יְדַעְתֶּם כִּי־יֵשׁ גּוֹיִם יוֹתֵר מֵאֶחָד הֲלֹא יְדַעְתֶּם כִּי־אֲנִי יְהוָה אֱלֹהֵיכֶם בָּרָאתִי אֶת־כׇּל־הָאָדָם וְכִי זֹכֵר אֲנִי אֶת־יֹשְׁבֵי אִיֵּי הַיָּם וְכִי מֹשֵׁל אֲנִי בַּשָּׁמַיִם מִמַּעַל וּבָאָרֶץ מִתָּחַת וְהוֹצֵאתִי דְבָרִי לִבְנֵי־הָאָדָם אַף גַּם לְכׇל־גּוֹיֵי הָאָרֶץ׃","en":"Know ye not that there are more nations than one? Know ye not that I, the Lord your God, have created all men, and that I remember those who are upon the isles of the sea; and that I rule in the heavens above and in the earth beneath; and I bring forth my word unto the children of men, yea, even upon all the nations of the earth?"},{"d":"2027-12-30","ref":"Mormon 7:9","b":"Mormon","c":7,"v":9,"he":"כִּי הִנֵּה זֹאת נִכְתְּבָה לְמַעַן תַּאֲמִינוּ בּוֹ וְאִם־תַּאֲמִינוּ בּוֹ תַּאֲמִינוּ גַּם־בָּזֹאת וְאִם־תַּאֲמִינוּ בָזֹאת תֵּדְעוּ עַל־אֲבוֹתֵיכֶם וְגַם הַנִּפְלָאוֹת אֲשֶׁר נַעֲשׂוּ בִּגְבוּרַת אֱלֹהִים בְּקִרְבָּם׃","en":"For behold, this is written for the intent that ye may believe that; and if ye believe that ye will believe this also; and if ye believe this ye will know concerning your fathers, and also the marvelous works which were wrought by the power of God among them."},{"d":"2027-12-31","ref":"Moroni 10:3","b":"Moroni","c":10,"v":3,"he":"הִנֵּה אַזְהִיר אֶתְכֶם כִּי בְּקׇרְאֲכֶם אֶת־הַדְּבָרִים הָאֵלֶּה אִם־חׇכְמָה הִיא בְּעֵינֵי אֱלֹהִים כִּי תִקְרְאוּם כִּי תִזְכְּרוּ מַה־רַב חֶסֶד יְהוָה עִם־בְּנֵי הָאָדָם מִבְּרִיאַת אָדָם וְעַד־הָעֵת אֲשֶׁר תְּקַבְּלוּ הַדְּבָרִים הָאֵלֶּה וַהֲגִיתֶם בִּלְבַבְכֶם׃","en":"Behold, I would exhort you that when ye shall read these things, if it be wisdom in God that ye should read them, that ye would remember how merciful the Lord hath been unto the children of men, from the creation of Adam even down until the time that ye shall receive these things, and ponder it in your hearts."},{"d":"2028-01-01","ref":"Moroni 10:4","b":"Moroni","c":10,"v":4,"he":"וּבְקַבֶּלְכֶם אֶת־הַדְּבָרִים הָאֵלֶּה אַזְהִיר אֶתְכֶם כִּי תִשְׁאֲלוּ מֵאֱלֹהִים הָאָב אֲשֶׁר־לְעוֹלָם בְּשֵׁם הַמָּשִׁיחַ אִם־לֹא אֱמֶת הַדְּבָרִים הָאֵלֶּה וְאִם־שָׁאֹל תִּשְׁאֲלוּ בְּלֵב תָּמִים וֶאֱמוּנָה בַּמָּשִׁיחַ יַגְלֶה לָכֶם אֲמִתָּתָם בְּכֹחַ רוּחַ־הַקֹּדֶשׁ׃","en":"And when ye shall receive these things, I would exhort you that ye would ask God, the Eternal Father, in the name of Christ, if these things are not true; and if ye shall ask with a sincere heart, with real intent, having faith in Christ, he will manifest the truth of it unto you, by the power of the Holy Ghost."},{"d":"2028-01-02","ref":"Moroni 10:5","b":"Moroni","c":10,"v":5,"he":"וּבְכֹחַ רוּחַ־הַקֹּדֶשׁ תּוּכְלוּ לָדַעַת אֲמִתַּת כׇּל־דָּבָר׃","en":"And by the power of the Holy Ghost ye may know the truth of all things."}]});
